import os
import sys

sys.dont_write_bytecode = True
try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass


def lp(path):
    """Long-path safe absolute path on Windows."""
    p = os.path.abspath(path)
    if os.name == "nt" and not p.startswith("\\\\?\\"):
        p = "\\\\?\\" + p
    return p


def rb(path):
    with open(path, "rb") as f:
        return f.read()


def wb(path, data):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    if isinstance(data, str):
        data = data.encode("utf-8")
    with open(path, "wb") as f:
        f.write(data)


def replace(path, old, new, count=1):
    data = rb(path)
    old_b = old.encode("utf-8") if isinstance(old, str) else old
    new_b = new.encode("utf-8") if isinstance(new, str) else new
    if data.count(old_b) < 1:
        sys.exit("solve: %s: pattern not found: %r" % (path, old_b[:60]))
    wb(path, data.replace(old_b, new_b, count) if count else data.replace(old_b, new_b))
import base64

FILES = {
 "analytics/events.py": "",
 "producer/event/event.go": "",
 "schema/order_event.schema.json": "",
 "web/src/orderEvent.ts": ""
}
DELETE = []
ANSWER = "Added `currency` end to end: schema (required, `^[A-Z]{3}$`), Go `OrderEvent.Currency` (`json:\"currency\"`, empty legacy currency published as PLN), TypeScript `OrderEvent.currency` with validation in `parseOrderEvent`, and Python `OrderEvent.currency` where archived events without the key default to PLN and malformed codes raise ValueError. Go, Node and Python tests and the contract check pass."

for rel in DELETE:
    os.remove(lp(rel))
for rel, b in sorted(FILES.items()):
    wb(lp(rel), base64.b64decode(b))
sys.stdout.write(ANSWER + "\n")
